	BookingRules_CreateBookingRuleTool       = newTool("booking_rules-create_booking_rule_v1", `Creates a BookingRule.`, BookingRules_CreateBookingRuleSchemaJSON, BookingRules_CreateBookingRuleOutputSchemaJSON, nil, "", nil)
	BookingRules_DeleteBookingRuleTool       = newTool("booking_rules-delete_booking_rule_v1", `Soft-deletes a BookingRule; it is purged at expire_time unless restored.`, BookingRules_DeleteBookingRuleSchemaJSON, BookingRules_DeleteBookingRuleOutputSchemaJSON, nil, "", nil)
